            if len(set(s[i:j])) == j - i:
                best = max(best, j - i)
    return best

def trap(h):
    n = len(h)
    left_max, right_max = [0] * n, [0] * n
    for i in range(n):
        left_max[i] = max(left_max[i - 1], h[i]) if i else h[i]
    for i in range(n - 1, -1, -1):
        right_max[i] = max(right_max[i + 1], h[i]) if i < n - 1 else h[i]
    return sum(min(left_max[i], right_max[i]) - h[i] for i in range(n))

