def two_sum_sorted(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        total = nums[left] + nums[right]
        if total == target:
            return [left, right]
        if total < target:
            left += 1
        else:
            right -= 1
    return []

def longest_unique(s):
    seen, left, best = set(), 0, 0
    for right, ch in enumerate(s):
        if ch in seen:
            seen.remove(s[left])
            left += 1
        seen.add(ch)
        best = max(best, right - left + 1)
    return best

def max_area(h):
    left, right, best = 0, len(h) - 1, 0
    while left < right:
        best = max(best, min(h[left], h[right]) * (right - left))
        if h[left] > h[right]:
            left += 1
        else:
            right -= 1
    return best

def three_sum(nums):
    nums = sorted(nums)
    out = []
    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = i + 1, len(nums) - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total < 0:
                left += 1
            elif total > 0:
                right -= 1
            else:
                out.append([nums[i], nums[left], nums[right]])
                left += 1
    return out
